import{showPlant}from './plant-visuals.js?v=20261023-physicscomplete01';
import{renderDiagram}from './visual.js?v=20261023-physicscomplete01';
import{leafFigure}from './plant-figures.js?v=20261023-physicscomplete01';
import{leafParts,leafLabels,environmentalTrials,stomaCounts,temperatureData,sugarDestinations,rootMovement}from './plant-models.js?v=20261023-physicscomplete01';
export{showPlant};
export function mountPlant(l,p,root,{save,done,feedback}){const w=p.widget,$=s=>root.querySelector(s),mode=l.widget,total=['plant-xylem','plant-stomata'].includes(mode)?4:3;w.task??=0;w.passed??=[];const task=w.task%total;
const field=(id,label,options,value)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([v,t])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${t}</option>`).join('')}</select>`;
const number=(id,label,value)=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" id="${id}" type="number" step="any" value="${value??''}">`;
const tail=`<div class="model-actions"><button class="secondary" id="checkPlant">Check reasoning</button><button class="secondary" id="nextPlant">Next challenge →</button></div><p id="plantProgress">${w.passed.length} / ${total} complete</p>`;
let html='',draw=()=>{},valid=()=>false,help='Compare the evidence and explain the result.';
const partChoices=leafParts.map(x=>[x.id,x.name]);
if(mode==='plant-leaf'){
if(task===0){w.leafIndex??=0;w.leafSeen??=[];const part=leafParts[w.leafIndex%6];html=`<p><b>1 / 3 · Match a structure to its role ·${w.leafIndex%6+1}/6</b></p><p>Inspect: <strong>${part.name}</strong></p><label class="field-label" for="leafExplode">Separate layers for inspection</label><input id="leafExplode" type="range" min="0" max="100" value="${w.leafExplode??30}">`+field('leafRole','Structure supports…',[['protect','Protection; light transmission'],['light','Absorb light with chloroplasts'],['gas','Gas movement through air spaces'],['water','Water and mineral-ion supply'],['sugar','Dissolved sugar transport'],['pore','Control a surface pore']],w.leafRole)+'<button class="secondary" id="recordLeaf">Record tissue →</button><p id="leafReadout"></p>';draw=()=>{showPlant('leaf:'+part.id,{explode:Number(w.leafExplode??30)/100});$('#leafReadout').textContent='Selected: '+part.name+' · symbolic colours and exaggerated layer spacing.';};valid=()=>leafParts.every(x=>w.leafSeen.includes(x.id));help='Use cell arrangement and location to connect the selected structure with its function. Record all six tissues/features.';}
if(task===1){w.tipsSeen??=[];html='<p><b>2 / 3 · Locate growth tissue</b></p>'+field('meristemTip','Inspect a growing tip',[['root','Root tip'],['shoot','Shoot tip']],w.meristemTip||'root')+'<button class="secondary" id="inspectTip">Highlight growing region →</button>'+field('meristemRole','Meristem cells…',[['divide','New cells for growth/differentiation'],['dead','Are all dead hollow vessels'],['pore','Only open and close leaf pores']],w.meristemRole);draw=()=>showPlant('whole',{tip:w.meristemTip||'root'});valid=()=>['root','shoot'].every(x=>w.tipsSeen.includes(x))&&w.meristemRole==='divide';help='Inspect both root and shoot tips. Meristems contain dividing cells for growth, rather than mature dead xylem.';}
if(task===2){w.labelIndex??=0;w.labelsSeen??=[];let i=w.labelIndex%5;html=`<p><b>3 / 3 · Build labels for a section ·${String.fromCharCode(65+i)}</b></p><p>Use the callout line and cell structure. This is a schematic, not a real micrograph.</p>`+field('leafLabel','Callout '+String.fromCharCode(65+i)+' identifies…',partChoices,w.leafLabel)+'<button class="secondary" id="recordLabel">Place label →</button>'+field('drawingRule','Scientific drawing approach',[['clear','Single lines; labels; valid scale'],['shade','Decorative shading instead of labels'],['guess','Invent a measured scale']],w.drawingRule);draw=()=>renderDiagram('Label the transverse section','Callouts A–E · original schematic',leafFigure({neutral:true})+'<p class="diagram-caption">Preparation for real observation and drawing.</p>','PLANT SECTION');valid=()=>leafLabels.every(x=>w.labelsSeen.includes(x))&&w.drawingRule==='clear';help='Follow each leader line: surface layer, columnar cells, irregular cells/air spaces, water-supply vein, guard-cell pair. Use clear scientific labels; a simulation is not physical drawing evidence.';}
}
else if(mode==='plant-root'){
if(task===0){w.waterSeen??=[];html='<p><b>1 / 3 · Predict net water movement</b></p>'+field('soilCondition','Soil compared with cell contents',[['dilute','More dilute soil solution'],['concentrated','More concentrated soil solution']],w.soilCondition||'dilute')+field('waterPrediction','Net movement through the membrane',[['in','Into the root hair'],['out','Out of the root hair']],w.waterPrediction)+'<button class="secondary" id="observeRootWater">Reveal net movement →</button><p id="waterReadout"></p>'+field('waterProcess','Process and requirement',[['osmosis','Osmosis; partially permeable membrane'],['pump','Active pumping of all water'],['sugar','Translocation of water as sugar']],w.waterProcess);draw=()=>{let c=w.observedSoil||'dilute';showPlant('root:water',{revealed:!!w.observedSoil,result:rootMovement('water',c).direction});$('#waterReadout').textContent=w.observedSoil?(c==='dilute'?'Net uptake from more dilute soil.':'Net loss to more concentrated soil.')+' Molecules still move both ways.':'Predict before revealing each soil comparison.';};valid=()=>['dilute','concentrated'].every(x=>w.waterSeen.includes(x))&&w.waterProcess==='osmosis';help='Compare both gradients. Net osmosis can reverse; the membrane is partially permeable and passive water movement is not an ATP pump.';}
if(task===1){w.energySeen??=[];html='<p><b>2 / 3 · Test energy-dependent ion uptake</b></p><p>Mineral ions are less concentrated in soil than inside the cell.</p>'+field('rootEnergy','Energy from respiration',[['on','Available'],['off','Removed in this counterfactual']],w.rootEnergy||'on')+field('ionPrediction','Active route outcome',[['in','Into higher cell ion concentration'],['stopped','This active route stops']],w.ionPrediction)+'<button class="secondary" id="observeRootIons">Compare active route →</button><p id="ionReadout"></p>'+field('ionReason','Explain the comparison',[['energy','Energy needed; passive routes remain'],['all','All molecular movement stops'],['water','Ions are transported by osmosis']],w.ionReason);draw=()=>{const on=w.observedEnergy!=='off';showPlant('root:ions',{revealed:!!w.observedEnergy,result:on?'in':'stopped'});$('#ionReadout').textContent=w.observedEnergy?(on?'Active ion uptake against the concentration gradient.':'Active route stopped; diffusion and osmosis can still occur.'):'Predict with and without energy, then compare.';};valid=()=>['on','off'].every(x=>w.energySeen.includes(x))&&w.ionReason==='energy';help='Compare both energy states. Active transport moves ions against their gradient and depends on respiration; it is distinct from passive water uptake.';}
if(task===2){w.hairsSeen??=[];html='<p><b>3 / 3 · Compare contact area</b></p>'+field('hairLength','Cell extension',[['short','Short extension'],['long','Long root hair']],w.hairLength||'short')+'<button class="secondary" id="compareHair">Inspect soil contact →</button>'+field('hairReason','Long hair supports uptake by…',[['area','Greater soil-contact surface area'],['light','Collect light for the leaf'],['make','Creating mineral ions']],w.hairReason)+field('rootRoute','Next transport route for water/ions',[['xylem','Root → stem xylem → leaf'],['phloem','Only sugar transport in phloem'],['air','Into blood through stomata']],w.rootRoute);draw=()=>showPlant('root:hair',{hair:w.hairLength||'short'});valid=()=>['short','long'].every(x=>w.hairsSeen.includes(x))&&w.hairReason==='area'&&w.rootRoute==='xylem';help='Compare both extensions, then connect greater contact area with absorption and xylem supply. No material is created by the hair.';}
}
else if(mode==='plant-xylem'){
if(task===0){w.ligninSeen??=[];html='<p><b>1 / 4 · Build a supported pathway</b></p>'+field('xylemWall','Wall comparison',[['lignin','Lignin reinforcement present'],['none','Reinforcement removed']],w.xylemWall||'lignin')+'<button class="secondary" id="inspectXylem">Compare wall →</button>'+field('xylemLumen','Inside a mature vessel',[['hollow','Hollow; no obstructing cytoplasm'],['solid','Solid; filled with guard cells']],w.xylemLumen)+field('xylemSupport','Role of lignin',[['strength','Strong walls; maintains open lumen'],['sugar','Makes dissolved sugar'],['pump','Pumps like a heart']],w.xylemSupport);draw=()=>showPlant('tube:xylem',{lignin:w.xylemWall!=='none'});valid=()=>['lignin','none'].every(x=>w.ligninSeen.includes(x))&&w.xylemLumen==='hollow'&&w.xylemSupport==='strength';help='Compare reinforced and unreinforced walls. Xylem is hollow; lignin supplies strength rather than active pumping or sugar manufacture.';}
if(task===1){w.streamStep??=0;html='<p><b>2 / 4 · Trace the transpiration stream</b></p>'+field('streamNext','Next process',[['evaporate','Evaporate from moist leaf cells'],['diffuse','Vapour diffuses through stomata'],['pull','Replacement water drawn up xylem']],w.streamNext)+'<button class="secondary" id="stepStream">Advance process →</button><p id="streamReadout"></p>'+field('streamPump','What drives this route?',[['loss','Leaf water loss draws water up'],['heart','A heart inside each leaf'],['sugar','Sugar turning into mineral ions']],w.streamPump);draw=()=>{showPlant('whole');$('#streamReadout').textContent=['Begin at moist leaf-cell surfaces.','Water has evaporated into leaf air spaces.','Vapour has diffused through the stomata.','Replacement water moves from roots through stem xylem to leaves.'][w.streamStep];};valid=()=>w.streamStep===3&&w.streamPump==='loss';help='Order evaporation, vapour diffusion, then replacement water drawn through xylem. Distinguish liquid movement from vapour loss.';}
if(task===2){w.bubbleDistance??=0;html='<p><b>3 / 4 · Plan and read a potometer</b></p>'+field('shootSetup','Shoot setup',[['underwater','Cut/fit under water; airtight'],['air','Cut dry and leave joints leaking']],w.shootSetup)+field('potoControl','Keep comparisons fair',[['match','Match conditions; acclimatise; repeat'],['change','Change conditions; unmatched shoots']],w.potoControl)+'<button class="secondary" id="stepBubble">Observe next minute →</button><p id="bubbleReadout"></p>'+field('potoMeaning','Bubble movement directly records…',[['uptake','Water uptake; estimates loss'],['exact','Exactly all water loss, always'],['sugar','Sugar production in the capillary']],w.potoMeaning);draw=()=>{showPlant('potometer',{distance:w.bubbleDistance});$('#bubbleReadout').textContent=`Original observation: ${w.bubbleDistance} mm after ${w.bubbleDistance/3} min. No leak or apparatus failure is modelled.`;};valid=()=>w.shootSetup==='underwater'&&w.potoControl==='match'&&w.bubbleDistance===12&&w.potoMeaning==='uptake';help='Use an airtight underwater setup and matched controls; read the four-minute displacement. Uptake estimates loss, and actual apparatus/safety skill needs school practice.';}
if(task===3){html='<p><b>4 / 4 · Convert distance to volume rate</b></p><p>Original record:12 mm in4 min; capillary radius0.5 mm; use π=3.14.</p>'+number('distanceRate','Distance rate / mm per min',w.distanceRate)+number('capillaryArea','Capillary cross-sectional area / mm²',w.capillaryArea)+number('uptakeVolume','Uptake volume / mm³',w.uptakeVolume)+number('volumeRate','Volume rate / mm³ per min',w.volumeRate);draw=()=>showPlant('potometer',{distance:12});valid=()=>Math.abs(Number(w.distanceRate)-3)<.001&&Math.abs(Number(w.capillaryArea)-.785)<.001&&Math.abs(Number(w.uptakeVolume)-9.42)<.001&&Math.abs(Number(w.volumeRate)-2.355)<.001;help='Distance/time=3mm/min. Area=πr²; volume=area×distance; divide volume by4min for volume rate. Keep squared/cubed units distinct.';}
}
else if(mode==='plant-stomata'){
if(task===0){w.poresSeen??=[];html='<p><b>1 / 4 · Balance gas exchange and water loss</b></p>'+field('poreState','Guard-cell pore',[['open','Open'],['closed','Closed']],w.poreState||'open')+field('porePrediction','Compared with an open pore, closure…',[['both','Less water loss; less CO₂ entry'],['water','Less water; unlimited CO₂ entry'],['none','Never affects either']],w.porePrediction)+'<button class="secondary" id="comparePore">Compare pore →</button><p id="poreReadout"></p>'+field('poreController','Cells controlling the pore',[['guard','Paired guard cells'],['xylem','Dead xylem vessels']],w.poreController);draw=()=>{showPlant('stoma:'+(w.observedPore||'open'));$('#poreReadout').textContent=w.observedPore==='closed'?'Less exchange through the pore: water conservation has a gas-exchange tradeoff.':'Open pore allows gas exchange and water-vapour loss.';};valid=()=>['open','closed'].every(x=>w.poresSeen.includes(x))&&w.porePrediction==='both'&&w.poreController==='guard';help='Compare both pore states. Guard cells regulate the opening; closing it restricts CO₂ entry as well as water loss.';}
if(task===1){w.envIndex??=0;w.envSeen??=[];let t=environmentalTrials[w.envIndex%4];html=`<p><b>2 / 4 · Change one factor ·${t.name}</b></p><p>${t.change}. Other factors matched; adequate water and moderate conditions.</p>`+field('envPrediction','Expected transpiration',[['faster','Usually faster'],['slower','Usually slower']],w.envPrediction)+'<button class="secondary" id="observeEnvironment">Reveal comparison →</button><p id="environmentReadout"></p>'+field('envLimit','Interpret this comparison',[['conditional','Conditional; stress may close pores'],['universal','Universal response at every extreme']],w.envLimit)+'<button class="secondary" id="recordEnvironment">Record factor →</button>';draw=()=>{showPlant('stoma:open',{emission:w.envObserved===t.id?(t.answer==='faster'?10:2):5});$('#environmentReadout').textContent=w.envObserved===t.id?t.why:'Baseline shown. Predict before revealing changed conditions. Droplet counts are symbolic.';};valid=()=>environmentalTrials.every(t=>w.envSeen.includes(t.id));help='Compare all four factors one at a time. Humidity reduces the gradient; air movement, moderate warming and brighter light can increase loss under the stated conditions.';}
if(task===2){w.fieldIndex??=0;w.fieldCounts??={};let i=w.fieldIndex%6,side=i<3?'upper':'lower',index=i%3;html=`<p><b>3 / 4 · Sample stomata ·${side} field${index+1}</b></p><p>Count pores, not individual guard cells. Use the same field area and an include-top/left, exclude-bottom/right boundary rule.</p>`+number('fieldCount','Observed pores in this field',w.fieldCount)+'<button class="secondary" id="recordField">Record field →</button><p id="fieldsReadout"></p>'+number('fieldArea','Each field0.5×0.5 mm · area / mm²',w.fieldArea)+number('upperMean','Upper mean / stomata per field',w.upperMean)+number('lowerMean','Lower mean / stomata per field',w.lowerMean)+number('upperDensity','Upper density / stomata per mm²',w.upperDensity)+number('lowerDensity','Lower density / stomata per mm²',w.lowerDensity)+field('samplingPlan','Sampling plan',[['representative','Representative, equal-area fields'],['busy','Choose only fields with most stomata']],w.samplingPlan);draw=()=>{showPlant('sample',{side,index});$('#fieldsReadout').textContent='Recorded counts: '+['upper','lower'].map((s,sidei)=>s+': '+[0,1,2].map(j=>w.fieldCounts[sidei*3+j]??'…').join(', ')).join(' · ');};valid=()=>Object.keys(w.fieldCounts).length===6&&Number(w.fieldArea)===.25&&Number(w.upperMean)===2&&Number(w.lowerMean)===12&&Number(w.upperDensity)===8&&Number(w.lowerDensity)===48&&w.samplingPlan==='representative';help='Record all six pore counts. Mean=sum÷3; field area=0.25mm²; density=mean÷area. Representative selection matters, and one leaf cannot represent all species.';}
if(task===3){w.graphY??=['','',''];html='<p><b>4 / 4 · Construct the uptake graph</b></p><p>Original temperature/°C → uptake/mm per min:20→2,25→3,30→4. Other factors matched.</p>'+temperatureData.map(([x],i)=>number('graph'+i,'Plot rate at '+x+'°C',w.graphY[i])).join('')+field('plantAxes','Axes and scale',[['correct','x: temperature; y: rate; valid scale'],['wrong','Unlabelled axes; temperature on both']],w.plantAxes)+field('plantGraphConclusion','Supported inference',[['range','Increase in this range only'],['forever','The same line continues at every temperature']],w.plantGraphConclusion);draw=()=>showPlant('graph',{points:temperatureData.map(([x],i)=>[x,w.graphY[i]]).filter(([,y])=>y!==''&&Number.isFinite(Number(y))&&Number(y)>=0&&Number(y)<=6)});valid=()=>temperatureData.every(([,y],i)=>w.graphY[i]!==''&&Number(w.graphY[i])===y)&&w.plantAxes==='correct'&&w.plantGraphConclusion==='range';help='Plot the three supplied y-values at their matching temperatures. Use units and a scale that fits; the trend is limited to this range and uptake only estimates transpiration.';}
}
else{
if(task===0){w.sugarPathIndex??=0;w.sugarPaths??=[];let dest=sugarDestinations[w.sugarPathIndex%2];html=`<p><b>1 / 3 · Build a sugar pathway ·${dest.name}</b></p><p>A photosynthesising leaf supplies this destination.</p>`+field('phloemCells','Tube structure',[['porous','Living tubes; porous end walls'],['xylem','Dead hollow vessels']],w.phloemCells)+field('phloemCargo','Cargo',[['sugar','Dissolved sugars'],['ions','Only mineral ions']],w.phloemCargo)+field('sugarDirection','Direction on this pathway',[['down','Down to roots below the leaf'],['up','Up to shoot above the leaf']],w.sugarDirection)+'<button class="secondary" id="recordSugarPath">Trace route →</button>';draw=()=>showPlant('tube:phloem',{direction:w.sugarDirection||dest.direction});valid=()=>['root','shoot'].every(x=>w.sugarPaths.includes(x));help='Connect elongated cells through end-wall pores, carry dissolved sugars and follow the destination: roots below or shoot tips above. Phloem is not always downward.';}
if(task===1){w.destinationIndex??=0;w.destinationsSeen??=[];let d=sugarDestinations[w.destinationIndex%3];html=`<p><b>2 / 3 · Use or store the sugar ·${d.name}</b></p>`+field('sugarUse','Relevant use at this destination',[['respire','Root respiration'],['build','Shoot growth'],['store','Starch storage']],w.sugarUse)+'<button class="secondary" id="recordSugarUse">Supply destination →</button>';draw=()=>showPlant('whole',{cargo:'sugar',direction:d.direction,tip:d.id==='root'?'root':'shoot'});valid=()=>sugarDestinations.every(d=>w.destinationsSeen.includes(d.id));help='Sugars can be used for respiration/growth or converted to storage material. Match the described destination and purpose; these are examples, not exclusive uses.';}
if(task===2){w.cargoIndex??=0;w.cargoSeen??=[];let i=w.cargoIndex%4,cases=[['Water','root to leaf','xylem'],['Dissolved sugar','leaf to root','phloem'],['Mineral ions','root to leaf','xylem'],['Dissolved sugar','leaf to shoot','phloem']],r=cases[i];html=`<p><b>3 / 3 · Compare transport tissues ·${i+1}/4</b></p><p>${r[0]}: ${r[1]}.</p>`+field('transportTissue','Choose the pathway',[['xylem','Xylem'],['phloem','Phloem']],w.transportTissue)+field('plantSystem','Roots, stems and leaves…',[['cooperate','Cooperate as an organ system'],['identical','Are identical cells doing every role']],w.plantSystem)+'<button class="secondary" id="recordCargo">Record cargo →</button>';draw=()=>showPlant('tube:'+r[2],{direction:i===1?'down':'up'});valid=()=>[0,1,2,3].every(i=>w.cargoSeen.includes(i));help='Water/mineral ions travel in xylem; dissolved sugars in phloem. Organs cooperate through these different routes.';}
}
root.innerHTML=html+tail;for(let el of root.querySelectorAll('select'))el.onchange=e=>{w[el.id]=e.target.value;save();if(['meristemTip','hairLength','xylemWall','sugarDirection'].includes(el.id))draw();};for(let el of root.querySelectorAll('input[type="number"]'))el.oninput=e=>{w[el.id]=e.target.value;save();};
const click=(id,fn)=>{if($('#'+id))$('#'+id).onclick=fn;};const record=(arr,key,ok,message=help)=>{if(!ok){feedback(message,true);return false;}if(!arr.includes(key))arr.push(key);save();feedback('Evidence recorded.');return true;};const remount=()=>mountPlant(l,p,root,{save,done,feedback});
if($('#leafExplode'))$('#leafExplode').oninput=e=>{w.leafExplode=e.target.value;save();draw();};
click('recordLeaf',()=>{let part=leafParts[w.leafIndex%6];if(record(w.leafSeen,part.id,w.leafRole===part.role)){w.leafIndex=(w.leafIndex+1)%6;w.leafRole='';save();remount();}});
click('inspectTip',()=>{record(w.tipsSeen,w.meristemTip||'root',true);draw();});
click('recordLabel',()=>{let id=leafLabels[w.labelIndex%5];if(record(w.labelsSeen,id,w.leafLabel===id)){w.labelIndex=(w.labelIndex+1)%5;w.leafLabel='';save();remount();}});
click('observeRootWater',()=>{let c=w.soilCondition||'dilute';if(!w.waterPrediction){feedback('Make a prediction first.',true);return;}w.observedSoil=c;record(w.waterSeen,c,w.waterPrediction===rootMovement('water',c).direction,'Compare the net direction with the relative concentration. More concentrated soil can draw water out.');save();draw();});
click('observeRootIons',()=>{let on=(w.rootEnergy||'on')==='on';if(!w.ionPrediction){feedback('Predict before observing.',true);return;}w.observedEnergy=on?'on':'off';record(w.energySeen,w.observedEnergy,w.ionPrediction===(on?'in':'stopped'),'Against-gradient mineral uptake needs energy. Removing that energy stops the active route, not all passive movement.');save();draw();});
click('compareHair',()=>{record(w.hairsSeen,w.hairLength||'short',true);draw();});
click('inspectXylem',()=>{record(w.ligninSeen,w.xylemWall||'lignin',true);draw();});
click('stepStream',()=>{let correct=['evaporate','diffuse','pull'][w.streamStep];if(w.streamStep>=3){feedback('The route is complete; explain what drives it.');return;}if(w.streamNext!==correct){feedback(help,true);return;}w.streamStep++;save();draw();});
click('stepBubble',()=>{w.bubbleDistance=Math.min(12,w.bubbleDistance+3);save();draw();});
click('comparePore',()=>{if(!w.porePrediction){feedback('Predict the tradeoff first.',true);return;}w.observedPore=w.poreState||'open';record(w.poresSeen,w.observedPore,true);draw();feedback(w.porePrediction==='both'?'Closure reduces both pathways.':'Closing the pore restricts CO₂ entry as well as water loss.',w.porePrediction!=='both');});
click('observeEnvironment',()=>{if(!w.envPrediction){feedback('Predict before revealing.',true);return;}w.envObserved=environmentalTrials[w.envIndex%4].id;save();draw();});
click('recordEnvironment',()=>{let t=environmentalTrials[w.envIndex%4];if(record(w.envSeen,t.id,w.envObserved===t.id&&w.envPrediction===t.answer&&w.envLimit==='conditional')){w.envIndex=(w.envIndex+1)%4;w.envPrediction='';save();remount();}});
click('recordField',()=>{let i=w.fieldIndex%6,s=i<3?'upper':'lower',count=stomaCounts[s][i%3];if(w.fieldCount===''||Number(w.fieldCount)!==count){feedback('Count each pore once, rather than each guard cell. Use the field boundary rule.',true);return;}w.fieldCounts[i]=Number(w.fieldCount);w.fieldIndex=(i+1)%6;w.fieldCount='';save();feedback('Field recorded.');remount();});
for(let i=0;i<3;i++)if($('#graph'+i))$('#graph'+i).oninput=e=>{w.graphY[i]=e.target.value;save();draw();};
click('recordSugarPath',()=>{let d=sugarDestinations[w.sugarPathIndex%2];if(record(w.sugarPaths,d.id,w.phloemCells==='porous'&&w.phloemCargo==='sugar'&&w.sugarDirection===d.direction)){w.sugarPathIndex=(w.sugarPathIndex+1)%2;w.sugarDirection='';save();remount();}});
click('recordSugarUse',()=>{let d=sugarDestinations[w.destinationIndex%3];if(record(w.destinationsSeen,d.id,w.sugarUse===d.use)){w.destinationIndex=(w.destinationIndex+1)%3;w.sugarUse='';save();remount();}});
click('recordCargo',()=>{let i=w.cargoIndex%4,correct=i%2===0?'xylem':'phloem';if(record(w.cargoSeen,i,w.transportTissue===correct&&w.plantSystem==='cooperate')){w.cargoIndex=(i+1)%4;w.transportTissue='';save();remount();}});
$('#checkPlant').onclick=()=>{if(!valid()){feedback(help,true);return;}if(!w.passed.includes(task))w.passed.push(task);if(w.passed.length===total){p.widgetDone=true;done();}save();$('#plantProgress').textContent=w.passed.length+' / '+total+' complete';feedback('Evidence and reasoning agree.');};$('#nextPlant').onclick=()=>{if(!w.passed.includes(task)){feedback('Complete this challenge first.',true);return;}w.task=(task+1)%total;save();feedback('');remount();};draw();}
